-- Importer-first expansion. Every relationship below was read from the named
-- ImportYeti company profile. Counts are relationship BOLs, not cargo value.

ON CONFLICT(id) DO UPDATE SET name=CASE WHEN length(excluded.name) >= length(importyeti_web_entities.name) THEN excluded.name ELSE importyeti_web_entities.name END,address=CASE WHEN importyeti_web_entities.address IS NULL OR NOT importyeti_web_entities.address GLOB '*[0-9]*' THEN excluded.address ELSE importyeti_web_entities.address END,country=excluded.country,source_url=excluded.source_url,search_query=excluded.search_query,captured_at=excluded.captured_at,raw_evidence=excluded.raw_evidence;

UPDATE importyeti_web_entities SET address='600 N Kilbourn Ave, Chicago, Il 60624, Us',total_shipments=1499,latest_shipment_date='2021-08-07',estimated_shipping_spend_usd=1300000,shipping_spend_coverage_percent=46,website='https://www.ldrind.com',captured_at='2026-08-05',raw_evidence='{"source_profile":"company/ldr-global-industries","alternate_names":23,"alternate_addresses":25,"supplier_rows_identified":7}' WHERE id='importer:ldr-global-industries';
