UPDATE importyeti_web_entities SET address='548 S Columbus Ave, Mount Vernon, Ny 10550, Us',total_shipments=383,latest_shipment_date='2022-03-25',estimated_shipping_spend_usd=247207,shipping_spend_coverage_percent=17,captured_at='2026-08-05',raw_evidence='{"source_profile":"company/giagni","alternate_names":3,"alternate_addresses":10,"supplier_rows_identified":7}' WHERE id='importer:giagni';

ON CONFLICT(id) DO UPDATE SET shipment_count=excluded.shipment_count,period_start=excluded.period_start,period_end=excluded.period_end,product_descriptions=excluded.product_descriptions,source_url=excluded.source_url,discovery_direction=excluded.discovery_direction,evidence_status=excluded.evidence_status,captured_at=excluded.captured_at;

UPDATE importyeti_web_relationships SET discovery_direction='both_profiles',evidence_status='cross_verified',source_url='https://www.importyeti.com/company/ldr-global-industries' WHERE id='guangdong-meijie-faucet:ldr-global-industries';
